def transform(grid):
    # Find where zeros are located horizontally (columns)
    all_zeros = []
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == 0:
                all_zeros.append(c)

    if not all_zeros:
        return None

    # Get unique zero column positions and find the range
    unique_zero_cols = sorted(list(set(all_zeros)))
    col_start = min(unique_zero_cols)

    # Extract 5 columns starting from where zeros begin
    # Rows 8 down to 1 (8 rows output)
    result = [grid[8-r][col_start:col_start+5] for r in range(8)]
    return result

